import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { toIsoTimestamp } from "@/types/common";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let ent: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  ent = await createTenant("vent", "enterprise");
  growth = await createTenant("vgrowth", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

beforeAll(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 1000;
});

type Kind = "issue" | "comment" | "project";
const ALL: Kind[] = ["issue", "comment", "project"];

function query(tenant: Tenant, q: string, kinds: Kind[] = ALL, projectId?: string) {
  return searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds,
    limit: 50,
    cursor: null,
    ...(projectId ? { projectId: projectId as never } : {}),
  });
}

function reindex(tenant: Tenant, subjectKind: Kind, subjectId: string) {
  return emit("search.reindex_requested", {
    orgId: tenant.org.id,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    subjectKind,
    subjectId,
  });
}

describe("ADR 0007 verification", () => {
  it("report 1: colon in a title is free text on Starter/Growth, no refusal", async () => {
    await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "Release 2: hotfix" }),
    );
    const page = await query(growth, "Release 2: hotfix", ["issue"]);
    expect(page.total).toBe(1);
    expect(page.items[0]?.title).toBe("Release 2: hotfix");
  });

  it("report 2: field tokens narrow the search on Enterprise, whichever entry point", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Flaky host" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "this one is flaky again",
      parentId: null,
      mentionedUserIds: [],
    });

    const byKind = await query(ent, "kind:comment flaky", ["issue"]);
    expect(byKind.total).toBe(1);
    expect(byKind.items[0]).toMatchObject({ kind: "comment", id: comment.id });

    const byIn = await query(ent, "in:comments flaky", ["issue"]);
    expect(byIn.total).toBe(1);
    expect(byIn.items[0]).toMatchObject({ kind: "comment" });

    const byProject = await query(ent, `project:${ent.project.id} flaky`, ["comment"]);
    expect(byProject.total).toBe(2);

    const otherProject = await query(ent, "project:prj_nope flaky", ALL);
    expect(otherProject.total).toBe(0);
  });

  it("report 3: comments are found by project scope", async () => {
    const page = await query(ent, "flaky", ["comment"], ent.project.id);
    expect(page.total).toBe(1);
    expect(page.items[0]).toMatchObject({ kind: "comment" });
  });

  it("report 4: % and _ are literal", async () => {
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Coverage at 100% now" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Coverage at 1000 now" }),
    );
    expect((await query(ent, "100%", ["issue"])).total).toBe(1);

    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake_case naming" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake case naming" }),
    );
    expect((await query(ent, "snake_case", ["issue"])).total).toBe(1);
  });

  it("report 5: without advanced_search only issues are searched, whatever kinds are asked", async () => {
    const issue = await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "Growth issue marker" }),
    );
    await commentService.createComment(growth.actors.member, {
      orgId: growth.org.id,
      issueId: issue.id,
      body: "Growth comment marker",
      parentId: null,
      mentionedUserIds: [],
    });
    const page = await query(growth, "marker", ALL);
    expect(page.items.every((hit) => hit.kind === "issue")).toBe(true);
    expect((await query(growth, "Growth comment marker", ["comment"])).total).toBe(0);
  });

  it("report 6: reindex never brings back archived or missing subjects", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Reindex archived marker" }),
    );
    await issueService.archiveIssue(ent.actors.member, ent.org.id, issue.id);
    await reindex(ent, "issue", issue.id);
    expect((await query(ent, "Reindex archived marker", ["issue"])).total).toBe(0);

    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: (await issueService.createIssue(
        ent.actors.member,
        issueInput(ent.org.id, ent.project.id, { title: "Host for comment" }),
      )).id,
      body: "Reindex comment marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await searchRepo.deleteSearchDocument(ent.org.id, "comment", comment.id);
    expect((await query(ent, "Reindex comment marker", ["comment"])).total).toBe(0);
    await reindex(ent, "comment", comment.id);
    const back = await query(ent, "Reindex comment marker", ["comment"], ent.project.id);
    expect(back.total).toBe(1);

    await searchRepo.deleteSearchDocument(ent.org.id, "project", ent.project.id);
    expect((await query(ent, "vent platform", ["project"])).total).toBe(0);
    await reindex(ent, "project", ent.project.id);
    expect((await query(ent, "vent platform", ["project"])).total).toBe(1);

    await reindex(ent, "comment", "cmt_missing_subject");
    expect((await query(ent, "cmt_missing_subject", ALL)).total).toBe(0);
  });

  it("edits re-index the comment body", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Edit host" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "Old body marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(ent.actors.member, {
      orgId: ent.org.id,
      commentId: comment.id,
      body: "New body marker",
    });
    expect((await query(ent, "New body marker", ["comment"], ent.project.id)).total).toBe(1);
    expect((await query(ent, "Old body marker", ["comment"])).total).toBe(0);
  });

  it("rebuild job restores project ids on comments and pages past the first 100 rows", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Rebuild host" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "Rebuild marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await searchRepo.upsertSearchDocument(ent.org.id, "comment", comment.id, comment.body, null);
    expect((await query(ent, "Rebuild marker", ["comment"], ent.project.id)).total).toBe(0);

    const { runSearchReindexJob: run } = await import("@/server/jobs/search-reindex-job");
    const result = await run(ent.org.id);
    expect(result.failed).toBe(0);
    expect((await query(ent, "Rebuild marker", ["comment"], ent.project.id)).total).toBe(1);

    for (let i = 0; i < 105; i += 1) {
      await issueService.createIssue(
        ent.actors.member,
        issueInput(ent.org.id, ent.project.id, { title: `Bulk marker ${i}` }),
      );
    }
    const bulk = await runSearchReindexJob(ent.org.id);
    expect(bulk.failed).toBe(0);
    expect(bulk.processed).toBeGreaterThanOrEqual(105);
  });
});

