      issueId: (await issueService.createIssue(
        ent.actors.member,
        issueInput(ent.org.id, ent.project.id, { title: "Host for comment" }),
      )).id,
      body: "Reindex comment marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await searchRepo.deleteSearchDocument(ent.org.id, "comment", comment.id);
    expect((await query(ent, "Reindex comment marker", ["comment"])).total).toBe(0);
    await reindex(ent, "comment", comment.id);
    const back = await query(ent, "Reindex comment marker", ["comment"], ent.project.id);
    expect(back.total).toBe(1);

    await searchRepo.deleteSearchDocument(ent.org.id, "project", ent.project.id);
    expect((await query(ent, "vent platform", ["project"])).total).toBe(0);
    await reindex(ent, "project", ent.project.id);
    expect((await query(ent, "vent platform", ["project"])).total).toBe(1);

    await reindex(ent, "comment", "cmt_missing_subject");
    expect((await query(ent, "cmt_missing_subject", ALL)).total).toBe(0);
  });

  it("edits re-index the comment body", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Edit host" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "Old body marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(ent.actors.member, {
      orgId: ent.org.id,
      commentId: comment.id,
      body: "New body marker",
    });
    expect((await query(ent, "New body marker", ["comment"], ent.project.id)).total).toBe(1);
    expect((await query(ent, "Old body marker", ["comment"])).total).toBe(0);
  });

  it("rebuild job restores project ids on comments and pages past the first 100 rows", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Rebuild host" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "Rebuild marker",
      parentId: null,
      mentionedUserIds: [],
    });
    await searchRepo.upsertSearchDocument(ent.org.id, "comment", comment.id, comment.body, null);
    expect((await query(ent, "Rebuild marker", ["comment"], ent.project.id)).total).toBe(0);

    const { runSearchReindexJob: run } = await import("@/server/jobs/search-reindex-job");
    const result = await run(ent.org.id);
    expect(result.failed).toBe(0);
    expect((await query(ent, "Rebuild marker", ["comment"], ent.project.id)).total).toBe(1);

    for (let i = 0; i < 105; i += 1) {
      await issueService.createIssue(
        ent.actors.member,
        issueInput(ent.org.id, ent.project.id, { title: `Bulk marker ${i}` }),
      );
    }
    const bulk = await runSearchReindexJob(ent.org.id);
    expect(bulk.failed).toBe(0);
    expect(bulk.processed).toBeGreaterThanOrEqual(105);
  });
});
